/// `struct opengl_client_context` field offsets (the same in both ABIs).
pub mod client {
    pub const OBJ: u64 = 0x0;
    pub const UNIX_HANDLE: u64 = 0x8;
    pub const UNIX_FUNCS: u64 = 0x10;
    pub const CURRENT_TID: u64 = 0x18;
    pub const LAST_ERROR: u64 = 0x1c;
    pub const CONTEXT_FLAGS: u64 = 0x20;
    pub const PROFILE_MASK: u64 = 0x24;
    pub const MAJOR_VERSION: u64 = 0x28;
    pub const MINOR_VERSION: u64 = 0x2c;
    pub const BROKEN_SHARING: u64 = 0x30;
    pub const EXTENSIONS: u64 = 0x34;
    pub const EXTENSION_COUNT: u64 = 0x36c;
    pub const EXTENSION_ARRAY: u64 = 0x370;
}
